mapper.select:
select ls.supplier_name as logisticsName, lc.name as channelName, lc.fee_rule as feeRule, st.id as templateId, st.billing_method as billingMethod, str.id as templateRuleId, str.start_weight as startWeight, str.end_weight as endWeight, str.first_weight_shipping_cost as firstWeightShippingCost, str.first_weight as firstWeight, str.first_weight_shipping_cost as firstWeightShippingCost, str.additional_unit_weight as additionalUnitWeight, str.additional_price as additionalPrice, str.shipping_price as shippingPrice, str.registration_cost as registrationCost, str.operating_cost as operatingCost, str.min_cost as minCost, str.to_country as toCountry, str.to_warehouse_name as toWarehouseName, str.region as region, st.effective_date as effectiveDate, st.expire_date as expireDate, st.weight_unit as weightUnit, st.volume_setting as volumeSetting, st.currency from logistics_supplier ls inner join logistics_channel lc on ls.id = lc.source_id and lc.is_deleted = false inner join shipping_template_ref_channel strc on strc.logistics_channel_id = lc.id and strc.is_deleted = false inner join shipping_template st on strc.main_id = st.id and st.is_deleted = false inner join shipping_template_rule str on str.main_id = st.id and str.is_deleted = false
ls.is_deleted = false and ls.disabled = false and st.disabled = false
and str.from_country in
#{item}
and str.to_country in
#{item}
and str.to_warehouse_name in
#{item}
and str.id in (select shipping_template_rule_id from shipping_region_city where is_deleted = false and str.region = region and city = #{params.city})
and lc.id in
#{item}
order by ls.id desc , lc.id desc,st.id desc , str.id desc
